Here's how to use MSTest's comparison assertions for your scoring system:

## Comparison Assertions

```csharp
// Assert.IsGreaterThan(lowerBound, actual) — actual must exceed lowerBound
Assert.IsGreaterThan(0, percentage);

// Assert.IsLessThan(upperBound, actual) — actual must be below upperBound  
Assert.IsLessThan(100, percentage);

// Assert.IsInRange(actual, low, high) — actual must be within [low, high]
Assert.IsInRange(percentage, 0.0, 100.0);
```

## Complete Test Class

```csharp
using Contoso.Scoring;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    [TestMethod]
    [DataRow(7, 10, 70.0)]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 10, 0.0)]
    public void CalculatePercentage_ValidInputs_ReturnsExpectedValue(
        int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);

        Assert.AreEqual(expected, result);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_IsInValidRange()
    {
        var result = _calculator.CalculatePercentage(3, 7);

        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(5, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    [TestMethod]
    [DataRow(95.0, "A")]
    [DataRow(90.0, "A")]
    [DataRow(85.0, "B")]
    [DataRow(80.0, "B")]
    [DataRow(75.0, "C")]
    [DataRow(70.0, "C")]
    [DataRow(65.0, "D")]
    [DataRow(60.0, "D")]
    [DataRow(55.0, "F")]
    [DataRow(0.0, "F")]
    public void GetGrade_AtBoundaries_ReturnsCorrectGrade(double percentage, string expected)
    {
        var result = _calculator.GetGrade(percentage);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    [DataRow(50.0, 100.0, 50.0)]
    [DataRow(100.0, 100.0, 100.0)]
    [DataRow(0.0, 100.0, 0.0)]
    public void NormalizeScore_ValidInputs_ReturnsExpectedValue(
        double rawScore, double maxRaw, double expected)
    {
        var result = _calculator.NormalizeScore(rawScore, maxRaw);

        Assert.AreEqual(expected, result);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calculator.NormalizeScore(150.0, 100.0);

        Assert.AreEqual(100.0, result);
        Assert.IsGreaterThan(0.0, result);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRawScore_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1.0, 100.0));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMaxRaw_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50.0, 0.0));
    }
}
```

## Key Takeaways

| Assertion | Meaning |
|-----------|---------|
| `Assert.IsGreaterThan(0.0, result)` | result > 0.0 |
| `Assert.IsLessThan(100.0, result)` | result < 100.0 |
| `Assert.IsInRange(result, 0.0, 100.0)` | 0.0 ≤ result ≤ 100.0 |

These produce much better failure messages than `Assert.IsTrue(result > 0)` — on failure they report both the bound and the actual value.
